using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using SharpHide.Vendor;

namespace ILTestLand;

[Virtualize]
[ControlFlow(MinBlocks = 2, MinSize = 4, MaxSize = 1600, BogusStates = 6, OpaqueDepth = 3,
    DecryptHashChance = 0.65)]
internal static class WorkflowCases {
    public static bool Workflow_0601() { var rows = "name,amount\na,100\nb,501".Split('\n').Skip(1); return rows.Sum(row => int.Parse(row.Split(',')[1], CultureInfo.InvariantCulture)) == 601; }
    public static bool Workflow_0602() { var fields = "602,active,uy".Split(','); return fields.Length == 3 && fields[0] == "602" && fields[2] == "uy"; }
    public static bool Workflow_0603() { var config = "host=localhost\nport=603\nsecure=true".Split('\n').Select(line => line.Split('=', 2)).ToDictionary(parts => parts[0], parts => parts[1]); return config["port"] == "603" && bool.Parse(config["secure"]); }
    public static bool Workflow_0604() { var logs = new[] { "INFO boot", "WARN slow", "ERROR 604", "WARN retry" }; return logs.Count(line => line.StartsWith("WARN", StringComparison.Ordinal)) == 2 && logs.Single(line => line.StartsWith("ERROR", StringComparison.Ordinal)).EndsWith("604", StringComparison.Ordinal); }
    public static bool Workflow_0605() { var stock = new Dictionary<string, int> { ["widget"] = 600 }; foreach (var delta in new[] { 10, -7, 2 }) stock["widget"] += delta; return stock["widget"] == 605; }
    public static bool Workflow_0606() { var lines = new[] { (Price: 100m, Quantity: 3), (Price: 50m, Quantity: 2) }; var subtotal = lines.Sum(line => line.Price * line.Quantity); var total = subtotal * 1.515m; return total == 606m; }
    public static bool Workflow_0607() { var samples = new[] { 600, 603, 606, 609, 612 }; var averages = samples.Window(3).Select(window => window.Average()).ToArray(); return averages.SequenceEqual(new[] { 603d, 606d, 609d }); }
    public static bool Workflow_0608() { var emails = new[] { "A@example.test", "a@EXAMPLE.test", "b@example.test" }; return emails.Distinct(StringComparer.OrdinalIgnoreCase).Count() == 2; }
    public static bool Workflow_0609() { var page = Enumerable.Range(1, 100).Skip(60).Take(9).ToArray(); return page.First() == 61 && page.Last() == 69 && page.Length == 9; }
    public static bool Workflow_0610() { var attempts = 0; while (attempts < 5) { attempts++; if (attempts == 3) break; } return attempts == 3; }
    public static bool Workflow_0611() { var state = "new"; foreach (var command in new[] { "pay", "pack", "ship" }) state = (state, command) switch { ("new", "pay") => "paid", ("paid", "pack") => "packed", ("packed", "ship") => "shipped", _ => "invalid" }; return state == "shipped"; }
    public static bool Workflow_0612() { var dependencies = new Dictionary<string, string[]> { ["build"] = ["restore"], ["test"] = ["build"], ["pack"] = ["test"] }; var done = new HashSet<string> { "restore" }; while (done.Count < 4) foreach (var step in dependencies) if (step.Value.All(done.Contains)) done.Add(step.Key); return done.SetEquals(new[] { "restore", "build", "test", "pack" }); }
    public static bool Workflow_0613() { var queue = new Queue<(int X, int Y, int D)>(); var seen = new HashSet<(int, int)>(); queue.Enqueue((0, 0, 0)); seen.Add((0, 0)); while (queue.Count > 0) { var current = queue.Dequeue(); if (current.X == 3 && current.Y == 2) return current.D == 5; foreach (var next in new[] { (current.X + 1, current.Y), (current.X, current.Y + 1) }) if (next.Item1 <= 3 && next.Item2 <= 2 && seen.Add(next)) queue.Enqueue((next.Item1, next.Item2, current.D + 1)); } return false; }
    public static bool Workflow_0614() { var costs = new[] { int.MaxValue, int.MaxValue, int.MaxValue, int.MaxValue }; costs[0] = 0; var edges = new[] { (0, 1, 4), (0, 2, 1), (2, 1, 2), (1, 3, 3), (2, 3, 9) }; for (var pass = 0; pass < 3; pass++) foreach (var (from, to, cost) in edges) if (costs[from] != int.MaxValue) costs[to] = Math.Min(costs[to], costs[from] + cost); return costs[3] == 6; }
    public static bool Workflow_0615() { var payload = Encoding.UTF8.GetBytes("case-615"); var checksum = payload.Aggregate(0u, (value, next) => (value * 31) ^ next); return checksum == payload.Aggregate(0u, (value, next) => (value * 31) ^ next); }
    public static bool Workflow_0616() { const string input = "aaabccccdd"; var encoded = new StringBuilder(); for (var i = 0; i < input.Length;) { var end = i + 1; while (end < input.Length && input[end] == input[i]) end++; encoded.Append(input[i]).Append(end - i); i = end; } return encoded.ToString() == "a3b1c4d2"; }
    public static bool Workflow_0617() { var uri = new UriBuilder("HTTPS", "Example.TEST", 443, "/api/../api/items").Uri; return uri.Scheme == "https" && uri.Host == "example.test" && uri.IsDefaultPort; }
    public static bool Workflow_0618() { var query = "page=6&size=18&active=true".Split('&').Select(part => part.Split('=', 2)).ToDictionary(parts => parts[0], parts => parts[1]); return int.Parse(query["page"], CultureInfo.InvariantCulture) * int.Parse(query["size"], CultureInfo.InvariantCulture) == 108 && bool.Parse(query["active"]); }
    public static bool Workflow_0619() { var slug = string.Join('-', " Case 619: Real World ".Trim().ToLowerInvariant().Split([' ', ':'], StringSplitOptions.RemoveEmptyEntries)); return slug == "case-619-real-world"; }
    public static bool Workflow_0620() { var counts = "red blue red green blue red".Split(' ').GroupBy(word => word).ToDictionary(group => group.Key, group => group.Count()); return counts["red"] == 3 && counts["blue"] == 2 && counts["green"] == 1; }
    public static bool Workflow_0621() { var values = new Dictionary<string, string> { ["name"] = "Ada", ["id"] = "621" }; var output = "Hello {{name}}, id={{id}}"; foreach (var value in values) output = output.Replace("{{" + value.Key + "}}", value.Value, StringComparison.Ordinal); return output == "Hello Ada, id=621"; }
    public static bool Workflow_0622() { const string value = "hello, \"world\""; var escaped = '"' + value.Replace("\"", "\"\"", StringComparison.Ordinal) + '"'; return escaped == "\"hello, \"\"world\"\"\""; }
    public static bool Workflow_0623() { const string row = "000623ACTIVE  "; var id = int.Parse(row[..6], CultureInfo.InvariantCulture); var status = row[6..].Trim(); return id == 623 && status == "ACTIVE"; }
    public static bool Workflow_0624() { var batches = Enumerable.Range(1, 24).Chunk(5).ToArray(); return batches.Length == 5 && batches[^1].SequenceEqual(new[] { 21, 22, 23, 24 }); }
    public static bool Workflow_0625() { var values = new[] { 6, 2, 5, 9, 1, 8 }; var maxima = values.Window(3).Select(window => window.Max()).ToArray(); return maxima.SequenceEqual(new[] { 6, 9, 9, 9 }); }
    public static bool Workflow_0626() { var cache = new Dictionary<int, string>(); var order = new LinkedList<int>(); foreach (var key in new[] { 1, 2, 3, 2, 4 }) { if (cache.ContainsKey(key)) order.Remove(key); else cache[key] = key.ToString(CultureInfo.InvariantCulture); order.AddFirst(key); if (order.Count > 3) { cache.Remove(order.Last!.Value); order.RemoveLast(); } } return order.SequenceEqual(new[] { 4, 2, 3 }) && !cache.ContainsKey(1); }
    public static bool Workflow_0627() { var memo = new Dictionary<int, int> { [0] = 0, [1] = 1 }; int Fib(int n) { if (memo.TryGetValue(n, out var value)) return value; return memo[n] = Fib(n - 1) + Fib(n - 2); } return Fib(15) == 610 && memo.Count == 16; }
    public static bool Workflow_0628() { var values = Enumerable.Range(600, 57).ToArray(); var low = 0; var high = values.Length - 1; while (low <= high) { var middle = (low + high) / 2; if (values[middle] == 628) return middle == 28; if (values[middle] < 628) low = middle + 1; else high = middle - 1; } return false; }
    public static bool Workflow_0629() { var intervals = new[] { (1, 4), (3, 8), (10, 12), (11, 15) }; var merged = new List<(int Start, int End)>(); foreach (var interval in intervals) { if (merged.Count == 0 || merged[^1].End < interval.Item1) merged.Add(interval); else merged[^1] = (merged[^1].Start, Math.Max(merged[^1].End, interval.Item2)); } return merged.SequenceEqual(new[] { (1, 8), (10, 15) }); }
    public static bool Workflow_0630() { var stack = new Stack<char>(); foreach (var character in "{[()()]}") { if ("{[(".Contains(character)) stack.Push(character); else if (stack.Count == 0 || Math.Abs(stack.Pop() - character) > 2) return false; } return stack.Count == 0; }
    public static bool Workflow_0631() { var stack = new Stack<int>(); foreach (var token in "60 10 + 2 * 1 -".Split(' ')) { if (int.TryParse(token, out var value)) stack.Push(value); else { var right = stack.Pop(); var left = stack.Pop(); stack.Push(token switch { "+" => left + right, "*" => left * right, "-" => left - right, _ => 0 }); } } return stack.Single() == 139; }
    public static bool Workflow_0632() { var command = "copy --force source.txt target.txt".Split(' '); var options = command.Where(part => part.StartsWith("--", StringComparison.Ordinal)).ToArray(); var operands = command.Skip(1).Where(part => !part.StartsWith("--", StringComparison.Ordinal)).ToArray(); return command[0] == "copy" && options.Single() == "--force" && operands.Length == 2; }
    public static bool Workflow_0633() { var versions = new[] { "1.10.0", "1.2.9", "2.0.0", "1.9.5" }.Select(Version.Parse).Order().ToArray(); return versions.First() == new Version(1, 2, 9) && versions.Last() == new Version(2, 0, 0); }
    public static bool Workflow_0634() { var parts = "6.3.4-beta.2".Split('-', 2); var version = Version.Parse(parts[0]); return version == new Version(6, 3, 4) && parts[1] == "beta.2"; }
    public static bool Workflow_0635() { var path = Path.GetFullPath(Path.Combine(Path.GetTempPath(), "case", "..", "635.txt")); return Path.GetFileName(path) == "635.txt" && Path.IsPathFullyQualified(path); }
    public static bool Workflow_0636() { var files = new[] { "a.cs", "b.json", "c.cs", "d.txt", "e.json" }; var groups = files.GroupBy(file => Path.GetExtension(file) ?? "").ToDictionary(group => group.Key, group => group.Count()); return groups[".cs"] == 2 && groups[".json"] == 2 && groups[".txt"] == 1; }
    public static bool Workflow_0637() { var types = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) { [".json"] = "application/json", [".txt"] = "text/plain" }; return types[Path.GetExtension("report.JSON")] == "application/json"; }
    public static bool Workflow_0638() { var segments = new[] { "api", "v1", "orders", "638" }.Select(Uri.EscapeDataString); return '/' + string.Join('/', segments) == "/api/v1/orders/638"; }
    public static bool Workflow_0639() { var arguments = new[] { "run", "file with spaces.txt", "--count=639" }; var rendered = string.Join(' ', arguments.Select(value => value.Contains(' ') ? $"\"{value}\"" : value)); return rendered == "run \"file with spaces.txt\" --count=639"; }
    public static bool Workflow_0640() { var errors = new List<string>(); var name = "Ada"; var age = 40; var email = "ada@example.test"; if (string.IsNullOrWhiteSpace(name)) errors.Add("name"); if (age is < 0 or > 130) errors.Add("age"); if (!email.Contains('@')) errors.Add("email"); return errors.Count == 0; }
    public static bool Workflow_0641() { const string card = "4111111111110641"; var masked = new string('*', card.Length - 4) + card[^4..]; return masked == "************0641"; }
    public static bool Workflow_0642() { var rearranged = "3214282912345698765432161182"; var remainder = 0; foreach (var character in rearranged) remainder = (remainder * 10 + character - '0') % 97; return remainder == 1; }
    public static bool Workflow_0643() { const string digits = "79927398713"; var sum = 0; var alternate = false; for (var i = digits.Length - 1; i >= 0; i--) { var value = digits[i] - '0'; if (alternate && (value *= 2) > 9) value -= 9; sum += value; alternate = !alternate; } return sum % 10 == 0; }
    public static bool Workflow_0644() { const string isbn = "0306406152"; var sum = 0; for (var i = 0; i < isbn.Length; i++) sum += (10 - i) * (isbn[i] - '0'); return sum % 11 == 0; }
    public static bool Workflow_0645() { var namespaceId = Guid.Parse("6ba7b810-9dad-11d1-80b4-00c04fd430c8"); var bytes = namespaceId.ToByteArray().Concat(Encoding.UTF8.GetBytes("case-645")).ToArray(); var hash = MD5.HashData(bytes); return new Guid(hash).ToByteArray().SequenceEqual(hash); }
    public static bool Workflow_0646() { var value = 646u; const string alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"; var output = new StringBuilder(); do { output.Insert(0, alphabet[(int)(value & 31)]); value >>= 5; } while (value != 0); return output.ToString() == "UG"; }
    public static bool Workflow_0647() { var bytes = new byte[] { 0x06, 0x47, 0xab, 0xcd }; var dump = string.Join(' ', bytes.Select(value => value.ToString("X2", CultureInfo.InvariantCulture))); return dump == "06 47 AB CD"; }
    public static bool Workflow_0648() { var before = "alpha\nbeta\ngamma".Split('\n'); var after = "alpha\nbeta2\ngamma\ndelta".Split('\n'); var changed = after.Where((line, index) => index >= before.Length || line != before[index]).ToArray(); return changed.SequenceEqual(new[] { "beta2", "delta" }); }
    public static bool Workflow_0649() { var words = "one two three four five six".Split(' '); var lines = new List<string>(); var current = ""; foreach (var word in words) { if (current.Length + word.Length + 1 > 10) { lines.Add(current); current = word; } else current = current.Length == 0 ? word : current + " " + word; } lines.Add(current); return lines.SequenceEqual(new[] { "one two", "three four", "five six" }); }
    public static bool Workflow_0650() { var sales = new[] { (Region: "north", Amount: 300), (Region: "south", Amount: 150), (Region: "north", Amount: 200) }; var report = sales.GroupBy(row => row.Region).ToDictionary(group => group.Key, group => group.Sum(row => row.Amount)); return report["north"] == 500 && report["south"] == 150 && report.Values.Sum() == 650; }

    private static IEnumerable<int[]> Window(this int[] values, int size) {
        for (var index = 0; index <= values.Length - size; index++)
            yield return values[index..(index + size)];
    }
}
